mapper.delete:
DELETE FROM sys_idempotency_record
WHERE id IN (SELECT id FROM (
    SELECT id FROM sys_idempotency_record
    WHERE status = #{processingStatus}
      AND update_time < #{before}
    LIMIT #{limit}
) AS stale_ids)

DELETE FROM sys_idempotency_record
WHERE id IN (SELECT id FROM (
    SELECT id FROM sys_idempotency_record
    WHERE expire_time < #{before}
    LIMIT #{limit}
) AS expired_ids)
